import test from 'node:test';
import assert from 'node:assert/strict';
import { EventEmitter } from 'node:events';
import { configuration, rolesFor, redactor, runtimeExpiry, assertRuntime, sample, sha, uploadArgs, allSettledOrThrow, preserveAndStop } from '../src/common.mjs';
import { dropbox } from '../src/dropbox.mjs';
import { cliEnvironment, sandboxCli, workerSourcePath } from '../src/sandbox.mjs';
import { runWorker } from '../src/worker.mjs';
import { verifyRun } from '../src/verify.mjs';
import { inspectShareable } from '../scripts/check-package.mjs';

const env = { DROPBOX_USER_ACCESS_TOKEN: '[REDACTED]', VERCEL_TEAM_ID: 'team_fixture', VERCEL_PROJECT_ID: 'prj_fixture' };
const response = (body, status = 200, metadata) => new Response(typeof body === 'string' ? body : JSON.stringify(body), {
  status, headers: { 'x-dropbox-request-id': 'fixture-request', ...(metadata ? { 'dropbox-api-result': JSON.stringify(metadata) } : {}) }
});
const runtime = () => ({ token: '[REDACTED]', expires_at: Date.now() + 60000, role: 'A', roles: ['A'],
  agent_id: 'fixture-A', run: 'fixture-run', workspace: '/agentfs-fixture', seeds: [] });

test('worker copy paths decode spaces and URL-encoded characters', () => {
  assert.equal(workerSourcePath('worker', 'file:///tmp/AgentFS%20Demo/src/sandbox.mjs'), '/tmp/AgentFS Demo/src/worker.mjs');
  assert.equal(workerSourcePath('common', 'file:///tmp/demo%23%25/src/sandbox.mjs'), '/tmp/demo#%/src/common.mjs');
});

test('config requires explicit non-placeholder credentials and one or three roles', () => {
  assert.deepEqual(rolesFor(3), ['A', 'B', 'C']); assert.deepEqual(rolesFor(1), ['A']);
  for (const n of [0, 2, 4, NaN]) assert.throws(() => rolesFor(n));
  assert.equal(configuration(env, 3).roles.length, 3);
  for (const key of Object.keys(env)) assert.throws(() => configuration({ ...env, [key]: '' }, 1));
  assert.throws(() => configuration({ ...env, DROPBOX_USER_ACCESS_TOKEN: '[REDACTED]' }, 1));
});
test('upload scope and revision preconditions', () => {
  const arg = uploadArgs('/test', '/test/file.txt', 'rev1');
  assert.deepEqual(arg.mode, { '.tag': 'update', update: 'rev1' });
  assert.equal(arg.strict_conflict, true); assert.equal(arg.autorename, false);
  assert.equal(uploadArgs('/test', '/test/new.txt').mode['.tag'], 'add');
  for (const path of ['/test-other/file', '/test/../other']) assert.throws(() => uploadArgs('/test', path));
});
test('runtime expiry uses returned lifetime and rejects expired or missing tokens', () => {
  assert.equal(runtimeExpiry(100, 200), 100200);
  for (const n of [undefined, 0, -1, 20, Infinity]) assert.throws(() => runtimeExpiry(n));
  assert.throws(() => assertRuntime({ token: 'fixture', expires_at: 100 }, 101));
  assert.throws(() => assertRuntime({ token: '', expires_at: 200 }, 101));
});
test('mint response token is registered before any response is recorded', async () => {
  const saved = [], redact = redactor(['fixture-user']); let captured;
  const api = dropbox({ token: '[REDACTED]', redact, record: async x => saved.push(JSON.stringify(x)),
    fetchImpl: async (url, options) => { captured = { url, options }; return response({ access_token: '[REDACTED]', expires_in: 14400 }); } });
  const minted = await api.rpc('mint', 'agent_filesystem/agents/access_token/mint', { agent: { '.tag': 'agent_id', agent_id: 'fixture' } });
  assert.equal(minted.access_token, 'fixture-runtime');
  assert.equal(captured.options.headers.Authorization, 'Bearer fixture-user');
  assert.equal(captured.options.redirect, 'error');
  assert.ok(saved.every(x => !x.includes('fixture-user') && !x.includes('fixture-runtime')));
  assert.equal(redact.text('fixture-user fixture-runtime'), '[REDACTED] [REDACTED]');
});
test('RPC authorization errors do not retry or print credentials', async () => {
  let count = 0;
  const api = dropbox({ token: '[REDACTED]', redact: redactor(['fixture-user']), record: async () => {},
    fetchImpl: async () => { count++; return response({ error_summary: 'expired_access_token/fixture-user' }, 401); } });
  await assert.rejects(api.rpc('check', 'check/user', {}), /HTTP 401/); assert.equal(count, 1);
});
test('network errors are redacted and recorded', async () => {
  const saved = [], api = dropbox({ token: '[REDACTED]', redact: redactor(['fixture-user']), record: async r => saved.push(JSON.stringify(r)),
    fetchImpl: async () => { throw new Error('failed fixture-user'); } });
  await assert.rejects(api.rpc('check', 'check/user', {}), /\[REDACTED\]/);
  assert.ok(saved.every(x => !x.includes('fixture-user')));
});
test('download omits content type and request body', async () => {
  let options;
  const api = dropbox({ token: '[REDACTED]', redact: redactor(['fixture-agent']), record: async () => {},
    fetchImpl: async (_url, x) => { options = x; return response('contents'); } });
  const r = await api.file('read', { path: '/test/file' });
  assert.equal(r.status, 200); assert.equal(options.body, undefined);
  assert.equal(options.headers['Content-Type'], undefined);
  assert.deepEqual(JSON.parse(options.headers['Dropbox-API-Arg']), { path: '/test/file' });
});
test('CLI environment does not inherit Dropbox, Gateway, or other application secrets', () => {
  assert.deepEqual(cliEnvironment({ HOME: '/home/test', PATH: '/bin', ...env, AI_GATEWAY_API_KEY: 'fixture' }),
    { HOME: '/home/test', PATH: '/bin', NO_COLOR: '1', CI: '1' });
});
test('CLI uses local pinned binary and explicit target, records nonzero errors', async () => {
  let invocation; const saved = [];
  const cli = sandboxCli({ config: configuration(env, 1), redact: redactor(['fixture-user']), record: async r => saved.push(JSON.stringify(r)),
    spawnImpl: (binary, args, options) => {
      invocation = { binary, args, options };
      const child = new EventEmitter(); child.stdout = new EventEmitter(); child.stderr = new EventEmitter();
      process.nextTick(() => { child.stderr.emit('data', 'fixture-user failure'); child.emit('close', 1, null); }); return child;
    } });
  await assert.rejects(cli('fixture', 'list', []), /failed/);
  assert.equal(invocation.binary, process.execPath); assert.ok(invocation.args[0].endsWith('/sandbox/bin/sandbox.mjs'));
  assert.ok(invocation.args.includes('team_fixture')); assert.ok(invocation.args.includes('prj_fixture'));
  assert.ok(saved.every(x => !x.includes('fixture-user')));
});
test('cleanup stops every confirmed sandbox despite preserve and stop failures', async () => {
  const agents = ['A', 'B', 'C'].map(role => ({ role, create_attempted: true, create_confirmed: true })), stops = [];
  await assert.rejects(preserveAndStop(agents, async a => { if (a.role === 'A') throw new Error('copy failed'); },
    async a => { stops.push(a.role); if (a.role === 'B') throw new Error('stop failed'); }), /cleanup failed/);
  assert.deepEqual(stops.sort(), ['A', 'B', 'C']);
  assert.deepEqual(agents.map(a => a.stopped), [true, false, true]);
});
test('parallel setup waits for every worker before cleanup can start', async () => {
  const done = [];
  await assert.rejects(allSettledOrThrow(['A', 'B'], async role => {
    if (role === 'A') throw new Error('setup failed');
    await new Promise(r => setTimeout(r, 5)); done.push(role);
  })); assert.deepEqual(done, ['B']);
});
test('failed or ambiguous creation never stops an unconfirmed sandbox', async () => {
  const stopped = [];
  await preserveAndStop([{ role:'collision', create_attempted:true, create_confirmed:false },
    { role:'owned', create_attempted:true, create_confirmed:true }], async () => {}, async a => stopped.push(a.role));
  assert.deepEqual(stopped, ['owned']);
});
test('CLI timeout settles without a child close event and allows cleanup to continue', async () => {
  const signals = [], saved = [];
  const cli = sandboxCli({ config:configuration(env,1), redact:redactor(), record:async r=>saved.push({...r}),
    spawnImpl:()=>{
      const child=new EventEmitter(); child.stdout=new EventEmitter(); child.stderr=new EventEmitter();
      child.kill=s=>{signals.push(s);return false;}; child.unref=()=>{}; return child;
    } });
  const result=await cli('unresponsive', 'list', [], {timeout:5,killGraceMs:5,allowFailure:true});
  assert.equal(result.exit_code,124); assert.equal(result.timed_out,true);
  assert.deepEqual(signals,['SIGTERM','SIGKILL']); assert.ok(saved.at(-1).finished_at);
});
test('worker rejects folder conflicts instead of treating any conflict as a race success', async () => {
  const r=runtime(), seed={label:'shared-1',path:r.workspace+'/shared-1.txt',rev:'old'};
  let calls=0;
  const result=await runWorker({...r,roles:['A','B','C'],seeds:[seed]},'write',100,{
    now:()=>0,wait:async()=>{},fetchImpl:async()=>{
      calls++;
      if(calls===1)return response(sample(r.run,seed.label,'seed'),200,{rev:'old'});
      if(calls===2)return response({rev:'own'});
      return response({error_summary:'path/conflict/folder/'},409);
    }
  });
  assert.equal(result.result,'FAILED'); assert.equal(calls,3);
});
test('single worker verifies exact roundtrip bytes', async () => {
  const r = runtime(), text = sample(r.run, 'separate', 'A');
  const write = await runWorker(r, 'write', 0, { fetchImpl: async (_url, opts) => {
    assert.equal(opts.body, text); assert.equal(JSON.parse(opts.headers['Dropbox-API-Arg']).mode['.tag'], 'add'); return response({ rev: 'r1' });
  } }); assert.equal(write.result, 'PASSED');
  const read = await runWorker(r, 'read', 0, { fetchImpl: async () => response(text) }); assert.equal(read.result, 'PASSED');
  const bad = await runWorker(r, 'read', 0, { fetchImpl: async () => response('wrong bytes') }); assert.equal(bad.result, 'FAILED');
});
test('expired token and missed barrier fail before upload', async () => {
  let calls = 0;
  const fetchImpl = async () => { calls++; return response({ rev: 'r1' }); };
  const expired = await runWorker({ ...runtime(), expires_at: 0 }, 'write', 0, { fetchImpl });
  assert.equal(expired.result, 'FAILED'); assert.equal(calls, 0);
  const missed = await runWorker({ ...runtime(), roles: ['A','B','C'] }, 'write', 1, { fetchImpl });
  assert.equal(missed.result, 'FAILED'); assert.equal(calls, 0);
});

function fixtureRun() {
  const run = { run: 'fixture-run', workspace: '/agentfs-fixture', agents: [], seeds: [], workers: {} };
  const entry = (label, arg, text, status = 200, metadata) => ({ label, arg, status, response_text: text,
    response_sha256: sha(text), metadata, request_id: 'fixture', started_at: '2026-10-09T00:00:00.000Z', finished_at: '2026-10-09T00:00:01.000Z' });
  for (let i = 1; i <= 3; i++) run.seeds.push({ label: `shared-${i}`, path: `${run.workspace}/shared-${i}.txt`, rev: `old-${i}` });
  for (const role of ['A','B','C']) {
    run.agents.push({ role, agent_id: `agent-${role}`, session_id: `sbx_fixture${role}`, create_confirmed: true, stopped: true });
    const base = { run: run.run, role, agent_id: `agent-${role}`, platform: 'linux', node: 'v24.0.0', result: 'PASSED' };
    const write = { ...base, requests: [] }, read = { ...base, requests: [] }; run.workers[role] = { write, read };
    write.requests.push({ ...entry('separate-write', uploadArgs(run.workspace, `${run.workspace}/${role}.txt`), '{"rev":"new"}'), request_sha256: sha(sample(run.run, 'separate', role)) });
    for (const who of ['A','B','C']) read.requests.push(entry(`read-${who}`, { path: `${run.workspace}/${who}.txt` }, sample(run.run,'separate',who)));
    for (const seed of run.seeds) {
      write.requests.push(entry(`initial-${seed.label}`, { path: seed.path }, sample(run.run, seed.label, 'seed'), 200, { rev: seed.rev }));
      write.requests.push({ ...entry(`race-${seed.label}`, uploadArgs(run.workspace, seed.path, seed.rev),
        role === 'A' ? '{"rev":"winner-rev"}' : '{"error_summary":"path/conflict/file/"}', role === 'A' ? 200 : 409), request_sha256: sha(sample(run.run, seed.label, role)) });
      read.requests.push(entry(`final-${seed.label}`, { path: seed.path }, sample(run.run,seed.label,'A'), 200, { rev:'winner-rev' }));
    }
  } return run;
}
test('three-agent verifier checks cross reads, races, overlap and stopped resources', () => {
  const summary = verifyRun(fixtureRun()); assert.equal(summary.exact_cross_reads, 9); assert.equal(summary.races.length, 3);
});
test('verifier rejects duplicate agents, failed cleanup, changed bytes and unrelated 409', () => {
  const edits = [
    r => { r.agents[1].agent_id = r.agents[0].agent_id; },
    r => { r.agents[2].stopped = false; },
    r => { r.workers.C.read.requests[0].response_text = 'changed'; },
    r => { const q=r.workers.B.write.requests.find(q=>q.label==='race-shared-1'); q.response_text='{"error_summary":"path/no_permission/"}'; q.response_sha256=sha(q.response_text); },
    r => { const q=r.workers.B.write.requests.find(q=>q.label==='race-shared-1'); q.response_text='{"error_summary":"path/conflict/folder/"}'; q.response_sha256=sha(q.response_text); },
    r => { r.workers.C.write.requests[0].started_at = '2026-10-09T00:00:02.000Z'; },
    r => { r.workers.B.write.requests.find(q=>q.label==='race-shared-1').status = 200; }
  ];
  for (const edit of edits) { const r=fixtureRun(); edit(r); assert.throws(()=>verifyRun(r)); }
});
test('package scanner rejects synthetic secrets and private paths', () => {
  assert.ok(inspectShareable('README.md', 'sl.' + 'a'.repeat(40)).length > 0);
  assert.ok(inspectShareable('README.md', '/' + 'Users/' + 'example/file').length > 0);
  assert.ok(inspectShareable('.env', 'secret').length > 0);
  assert.ok(inspectShareable('.env.example', 'DROPBOX_USER_ACCESS_TOKEN=[REDACTED]').length > 0);
  assert.deepEqual(inspectShareable('.env.example', 'DROPBOX_USER_ACCESS_TOKEN=[REDACTED]'), []);
});

